<div class="d-flex justify-content-between mb-3"><h4>Attendance history</h4><a class="btn btn-outline-secondary" href="<?= url('attendance/index') ?>"><i class="bi bi-arrow-left"></i> Back</a></div>
<form method="get" class="row g-2 mb-3"><input type="hidden" name="r" value="attendance/history">
<div class="col-md-4"><select class="form-select" name="employee" required><option value="">-- Employee --</option><?php foreach ($employees as $e2): ?><option value="<?= (int)$e2['id'] ?>" <?= $eid === (int)$e2['id'] ? 'selected' : '' ?>><?= e($e2['emp_no'] . ' - ' . $e2['full_name']) ?></option><?php endforeach; ?></select></div>
<div class="col-auto"><input type="date" class="form-control" name="from" value="<?= e($from) ?>"></div><div class="col-auto"><input type="date" class="form-control" name="to" value="<?= e($to) ?>"></div><div class="col-auto"><button class="btn btn-outline-secondary">Show</button></div></form>
<?php if ($emp): ?><div class="card"><div class="table-responsive"><table class="table table-sm mb-0"><thead class="table-light"><tr><th>Date</th><th>Status</th><th>In</th><th>Out</th><th>Note</th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr><td><?= e($r['att_date']) ?></td><td><?= badge($r['status']) ?></td><td><?= e(substr((string)$r['check_in'], 0, 5)) ?></td><td><?= e(substr((string)$r['check_out'], 0, 5)) ?></td><td><?= e($r['note']) ?></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="5" class="text-center text-muted py-3">No records in range.</td></tr><?php endif; ?></tbody></table></div></div><?php endif; ?>
